def format_simple_output(results):
    """Format results as simple text."""
    if not results:
        click.echo("No proprietary software found.")
        return

    click.echo("Proprietary software detected:")
    for manager_name, packages in results.items():
        click.echo(f"\n{manager_name}:")
        for package in packages:
            licenses_str = ", ".join(package.get("licenses", ["unknown"]))
            detection_reason = package.get("detection_reason", "Unknown")
            click.echo(f"  - {package['name']} ({package['version']}) - {licenses_str}")
            click.echo(f"    Reason: {detection_reason}")
